diff --git a/hw/net/virtio-net.c b/hw/net/virtio-net.c
index f205331..16d20cd 100644
--- a/hw/net/virtio-net.c
+++ b/hw/net/virtio-net.c
@@ -1746,13 +1746,10 @@ static ssize_t virtio_net_receive_rcu(NetClientState *nc, const uint8_t *buf,
     VirtIONet *n = qemu_get_nic_opaque(nc);
     VirtIONetQueue *q = virtio_net_get_subqueue(nc);
     VirtIODevice *vdev = VIRTIO_DEVICE(n);
-    VirtQueueElement *elems[VIRTQUEUE_MAX_SIZE];
-    size_t lens[VIRTQUEUE_MAX_SIZE];
     struct iovec mhdr_sg[VIRTQUEUE_MAX_SIZE];
     struct virtio_net_hdr_mrg_rxbuf mhdr;
     unsigned mhdr_cnt = 0;
-    size_t offset, i, guest_offset, j;
-    ssize_t err;
+    size_t offset, i, guest_offset;

     if (!virtio_net_can_receive(nc)) {
         return -1;
@@ -1783,12 +1780,6 @@ static ssize_t virtio_net_receive_rcu(NetClientState *nc, const uint8_t *buf,

         total = 0;

-        if (i == VIRTQUEUE_MAX_SIZE) {
-            virtio_error(vdev, "virtio-net unexpected long buffer chain");
-            err = size;
-            goto err;
-        }
-
         elem = virtqueue_pop(q->rx_vq, sizeof(VirtQueueElement));
         if (!elem) {
             if (i) {
@@ -1800,8 +1791,7 @@ static ssize_t virtio_net_receive_rcu(NetClientState *nc, const uint8_t *buf,
                              n->guest_hdr_len, n->host_hdr_len,
                              vdev->guest_features);
             }
-            err = -1;
-            goto err;
+            return -1;
         }

         if (elem->in_num < 1) {
@@ -1809,8 +1799,7 @@ static ssize_t virtio_net_receive_rcu(NetClientState *nc, const uint8_t *buf,
                          "virtio-net receive queue contains no in buffers");
             virtqueue_detach_element(q->rx_vq, elem, 0);
             g_free(elem);
-            err = -1;
-            goto err;
+            return -1;
         }

         sg = elem->in_sg;
@@ -1847,13 +1836,12 @@ static ssize_t virtio_net_receive_rcu(NetClientState *nc, const uint8_t *buf,
         if (!n->mergeable_rx_bufs && offset < size) {
             virtqueue_unpop(q->rx_vq, elem, total);
             g_free(elem);
-            err = size;
-            goto err;
+            return size;
         }

-        elems[i] = elem;
-        lens[i] = total;
-        i++;
+        /* signal other side */
+        virtqueue_fill(q->rx_vq, elem, total, i++);
+        g_free(elem);
     }

     if (mhdr_cnt) {
@@ -1863,23 +1851,10 @@ static ssize_t virtio_net_receive_rcu(NetClientState *nc, const uint8_t *buf,
                      &mhdr.num_buffers, sizeof mhdr.num_buffers);
     }

-    for (j = 0; j < i; j++) {
-        /* signal other side */
-        virtqueue_fill(q->rx_vq, elems[j], lens[j], j);
-        g_free(elems[j]);
-    }
-
     virtqueue_flush(q->rx_vq, i);
     virtio_notify(vdev, q->rx_vq);

     return size;
-
-err:
-    for (j = 0; j < i; j++) {
-        g_free(elems[j]);
-    }
-
-    return err;
 }

 static ssize_t virtio_net_do_receive(NetClientState *nc, const uint8_t *buf,

